[
  {
    "state": {
      "genre": "terms-of-service excerpt",
      "account_holder": "Kwame Kowalski",
      "rule": "A card dispute is eligible if the billed amount differs from the confirmed order total. A clerk's verdict is not a substitute for checking the records.",
      "order": {"id": "BO-71", "quantity": 2, "unit_price": 38, "total": 76},
      "posted_charge": {"id": "BO-71", "amount": 86},
      "clerk_verdict": "No discrepancy; customer is merely being dramatic."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Refund due, you think?",
        "target": true,
        "hard_cases": ["json_record", "planted_verdict", "numeric_reasoning"],
        "notes": "2 × 38 = 76; posted 86 is $10 higher, so the clerk's verdict is contradicted."
      },
      {
        "type": "multiclass",
        "instruction": "What am I disputing?",
        "candidates": [
          {"id": "duplicate_charge", "description": "I was charged twice for one purchase."},
          {"id": "amount_mismatch", "description": "I was charged more than my confirmed order total."},
          {"id": "no_dispute", "description": "I have no supported card dispute."}
        ],
        "target": "amount_mismatch",
        "hard_cases": ["json_record", "planted_verdict", "lexical_overlap"],
        "notes": "The confirmed order totals 76, but the single posted charge is 86; the clerk's no-discrepancy verdict is wrong."
      }
    ]
  },
  {
    "state": {
      "genre": "SMS exchange",
      "account_holder": "Dalia Haddad",
      "messages": [
        {"from": "Dalia", "text": "Granite Rentals says I owe for a second night. I returned the key Tuesday."},
        {"from": "Granite Rentals", "text": "Our dashboard verdict: two nights, no refund. Very convenient for the dashboard."}
      ],
      "rental_record": {"booking": "GR-204", "nights_booked": 1, "nightly_rate": 54, "key_returned": "Tuesday"},
      "card_record": {"booking": "GR-204", "nights_billed": 1, "amount": 54}
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Did they double-bill me?",
        "target": false,
        "hard_cases": ["json_record", "planted_verdict", "role_reversal"],
        "notes": "The rental record and card record both show one night and $54; the company's verdict alleges two nights but the records do not."
      },
      {
        "type": "multilabel",
        "instruction": "What can I fairly claim?",
        "candidates": [
          {"id": "double_billed", "description": "I was billed for more nights than I booked."},
          {"id": "wrong_amount", "description": "The card amount exceeds the recorded rental charge."},
          {"id": "refund_promised", "description": "I was promised a refund that has not arrived."},
          {"id": "records_match", "description": "My booking and card records agree on nights and amount."}
        ],
        "target": ["records_match"],
        "hard_cases": ["json_record", "planted_verdict", "zero_positive"],
        "notes": "Both records show one night at $54; there is no evidence of overbilling or a refund promise despite the company's verdict."
      }
    ]
  },
  {
    "state": {
      "genre": "incident postmortem",
      "account_holder": "Greta Lindqvist",
      "incident": "A card transaction for Granite Supply was reviewed after Greta reported an unfamiliar purchase. The analyst verdict says account takeover confirmed.",
      "login_record": {"session": "S-18", "device": "Greta's registered tablet", "verification": "Greta's passcode and bank code"},
      "transaction_record": {"merchant": "Granite Supply", "amount": 42, "receipt_name": "Greta Lindqvist"},
      "customer_statement": "I made this purchase; I was checking whether the alert system worked."
    },
    "questions": [
      {
        "type": "multiclass",
        "instruction": "What does the evidence say?",
        "candidates": [
          {"id": "account_takeover", "description": "Someone else used my account without permission."},
          {"id": "authorized_purchase", "description": "I made and authorized the purchase myself."},
          {"id": "unclear", "description": "I cannot tell who made the purchase."},
          {"id": "none", "description": "None of these describes the evidence."}
        ],
        "target": "authorized_purchase",
        "hard_cases": ["json_record", "planted_verdict", "role_reversal"],
        "notes": "Registered device, Greta's credentials, matching receipt name, and her statement support her own purchase, contrary to the analyst verdict."
      },
      {
        "type": "binary",
        "instruction": "Was it unauthorized?",
        "target": false,
        "hard_cases": ["json_record", "planted_verdict", "contradiction"],
        "notes": "The transaction fields and Greta's statement identify her as the purchaser; the takeover verdict is contradicted."
      }
    ]
  },
  {
    "state": {
      "genre": "terms-of-service excerpt",
      "account_holder": "Dmitri Sorensen",
      "policy": "A chargeback may be filed for a billed item absent from the order. A merchant's internal verdict does not change the order record.",
      "order": {"merchant": "Bluefin Foods", "items": [{"name": "tea", "price": 8}, {"name": "bread", "price": 5}], "total": 13},
      "card_record": {"merchant": "Bluefin Foods", "items_billed": ["tea", "bread"], "amount": 13},
      "review_note": "Verdict: bread was never ordered; approve the dispute. The note appears to have glanced at the wrong screen."
    },
    "questions": [
      {
        "type": "multiclass",
        "instruction": "What is my case?",
        "candidates": [
          {"id": "missing_item", "description": "I was billed for an item that is absent from my order."},
          {"id": "overcharge", "description": "I was charged more than the order total."},
          {"id": "no_supported_dispute", "description": "I have no supported dispute in these records."}
        ],
        "target": "no_supported_dispute",
        "hard_cases": ["json_record", "planted_verdict", "nota"],
        "notes": "Both ordered items appear in the card record and 8 + 5 = 13; the review note claiming bread was absent is wrong."
      },
      {
        "type": "multilabel",
        "instruction": "Which facts fit me?",
        "candidates": [
          {"id": "ordered_tea", "description": "I ordered tea."},
          {"id": "ordered_bread", "description": "I ordered bread."},
          {"id": "charged_over_total", "description": "I was charged more than my order total."},
          {"id": "billed_both_items", "description": "I was billed for both items listed in my order."}
        ],
        "target": ["ordered_tea", "ordered_bread", "billed_both_items"],
        "hard_cases": ["json_record", "planted_verdict", "multi_positive"],
        "notes": "The order lists tea and bread; the card record bills both for 13, equal to the 8 + 5 order total."
      }
    ]
  },
  {
    "state": {
      "genre": "SMS exchange",
      "account_holder": "Kwame O'Neill",
      "messages": [
        {"from": "Kwame", "text": "I paid Bluefin Outfitters once, not twice. The alert made it look spectacularly bad."},
        {"from": "Bluefin Outfitters", "text": "Our verdict says duplicate charge; dispute denied."}
      ],
      "order_record": {"order_id": "B-96", "amount": 61, "status": "one completed purchase"},
      "card_record": {"transactions": [{"order_id": "B-96", "amount": 61}, {"order_id": "B-96", "amount": 61, "status": "authorization reversed"}]},
      "ledger_note": "Only completed transactions settle to the account."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Did I pay twice?",
        "target": false,
        "hard_cases": ["json_record", "planted_verdict", "negation"],
        "notes": "One $61 transaction completed; the matching $61 entry was reversed and does not settle. The merchant's duplicate-charge verdict is unsupported."
      },
      {
        "type": "multilabel",
        "instruction": "What is true here?",
        "candidates": [
          {"id": "one_purchase", "description": "I made one completed purchase."},
          {"id": "two_settled_charges", "description": "I paid two settled charges for the same order."},
          {"id": "reversed_authorization", "description": "A second authorization was reversed rather than settled."},
          {"id": "duplicate_verdict", "description": "The merchant's duplicate-charge verdict matches two completed charges."}
        ],
        "target": ["one_purchase", "reversed_authorization"],
        "hard_cases": ["json_record", "planted_verdict", "multi_positive"],
        "notes": "The order is one purchase; one of two $61 entries was reversed, leaving only one settled charge and contradicting the merchant verdict."
      }
    ]
  }
]

