[
  {
    "state": {
      "document_type": "Overly polite status update to a manager",
      "company": "Foxglove Freight",
      "employee": "Hiro Tanaka",
      "policy_excerpt": "For this review, an expense is reimbursable only when the approved amount is no more than the amount actually paid, the receipt is dated during the active assignment, and the item is not expressly marked personal. A supervisor's summary is a review aid, not a substitute for the transaction fields. The active assignment ran from 2026-05-01 through 2026-05-31, inclusive. Receipts submitted by June 10 are timely. Amounts below are in dollars; tax is included in the paid amount.",
