        {
          "claim_id": "FX-801",
          "category": "lodging",
          "assignment_id": "MAY-26",
          "assignment_dates": [
            "2026-05-01",
            "2026-05-31"
          ],
          "receipt_date": "2026-05-28",
          "submitted_date": "2026-06-09",
          "receipt_paid": 142,
          "approved_amount": 142,
          "personal_marker": false,
          "supervisor_annotation": "Approved; reimburse in full."
        },
        {
          "claim_id": "FX-802",
          "category": "dinner",
          "assignment_id": "MAY-26",
          "receipt_date": "2026-05-18",
          "submitted_date": "2026-06-09",
